"""Support for classes generated by `pyquickbase codegen`. No network access."""

from collections.abc import Collection, Iterable, Mapping, Sequence
from dataclasses import dataclass, fields
from decimal import Decimal
from typing import TYPE_CHECKING, Any, ClassVar, Generic, Self, TypeVar

from ._models import RECORD_ID_FIELD, Field, Record
from ._query import F
from .errors import InvalidResponseError, InvalidValueError, QueryError, SchemaMismatchError

_BUILT_IN_FIELDS = 5
WRITABLE_TYPES = {
    "text",
    "text-multiple-choice",
    "text-multi-line",
    "rich-text",
    "numeric",
    "currency",
    "rating",
    "percent",
    "multitext",
    "email",
    "url",
    "duration",
    "date",
    "timestamp",
    "timeofday",
    "checkbox",
    "user",
    "multiuser",
    "phone",
    "file",
    "predecessor",
}


def is_writable(field: Field) -> bool:
    """Whether a field can be written. Types we haven't confirmed count as read-only."""
    return field.mode is None and field.id > _BUILT_IN_FIELDS and field.type in WRITABLE_TYPES


def read_as(field: Field) -> str:
    """How a generated class converts a field's value, as a query returns every number as a float.

    `decimal_places` is only how a number is displayed, so `TypedRecord` still checks each value.
    """
    if field.type == "currency":
        return "decimal"
    if field.type == "numeric" and (field.is_foreign_key or field.decimal_places == 0):
        return "int"
    return ""


class Unset:
    """The type of `UNSET`, which means "leave this field alone", unlike None, which clears it."""

    __slots__ = ()

    def __repr__(self) -> str:
        return "UNSET"


UNSET = Unset()


class TypedField(F):
    """A field of a generated class, usable in queries like `F`. `desc` sorts it descending."""

    __slots__ = ()

    @property
    def id(self) -> int:
        """The field's ID."""
        return self._field  # pyright: ignore[reportReturnType]

    @property
    def desc(self) -> int:
        """This field in `order_by`, sorted descending."""
        return -self.id


OrderBy = TypedField | int | Sequence[TypedField | int] | None
"""What a typed table's `order_by` takes: fields of the class or their IDs, alone or in a list."""

Select = TypedField | Sequence[TypedField] | None
"""What a typed table's `select` takes: fields of the class, alone or in a list."""


_ORDER_BY_HELP = (
    "order_by takes a field of the generated class or its ID, or a list of them, such as "
    "Tasks.fields.title, or Tasks.fields.title.desc for descending."
)


def _order_ref(ref: TypedField | int) -> int:
    if isinstance(ref, TypedField):
        return ref.id
    if isinstance(ref, bool) or not isinstance(ref, int):  # pyright: ignore[reportUnnecessaryIsInstance]
        raise QueryError(_ORDER_BY_HELP)
    return ref


def order_refs(order_by: OrderBy) -> list[int] | None:
    """Turn `order_by` into field IDs, where a negative ID sorts descending.

    Labels are refused, because generated classes use IDs so that renaming a label can't break them.
    """
    if order_by is None:
        return None
    if isinstance(order_by, TypedField | int):
        return [_order_ref(order_by)]
    if isinstance(order_by, str) or not isinstance(order_by, Iterable):  # pyright: ignore[reportUnnecessaryIsInstance]
        raise QueryError(_ORDER_BY_HELP)
    return [_order_ref(ref) for ref in order_by]


@dataclass(frozen=True, slots=True)
class Column:
    """How a generated attribute maps to a field. `type` is what codegen saw.

    Attributes:
        name: The attribute's name on the generated class.
        id: The field's ID.
        type: The field's type when the class was generated.
        writable: Whether the class lets you write this field.
        label: The field's label when the class was generated.
        read_as: `int` or `decimal` when a number gets converted, and empty otherwise.
    """

    name: str
    id: int
    type: str
    writable: bool
    label: str
    read_as: str = ""


R = TypeVar("R", bound="TypedRecord")


class Row(dict[int, Any], Generic[R]):
    """Values to write, by field ID, from a generated class's `new()` or `change()`.

    It's tied to its class, so a type checker refuses a row meant for another table, and a typed
    table raises `InvalidValueError` for one.

    Attributes:
        table_id: The table it was made for.
    """

    def __init__(
        self, values: Mapping[int, Any] | None = None, *, table_id: str | None = None
    ) -> None:
        super().__init__(values or {})
        self.table_id = table_id


@dataclass(frozen=True, slots=True, kw_only=True)
class TypedPage(Generic[R]):
    """One page of records as instances of a generated class.

    Attributes:
        records: The records on this page, as instances of the class.
        total: How many records match, not just the ones on this page.
        skip: How many matching records came before this page.
    """

    records: tuple[R, ...]
    total: int
    skip: int

    @property
    def has_more(self) -> bool:
        """Whether more matching records come after this page."""
        return self.next_skip < self.total

    @property
    def next_skip(self) -> int:
        """The `skip` that fetches the following page."""
        return self.skip + len(self.records)


def _converted(column: Column, value: Any) -> Any:
    if value is None or not column.read_as:
        return value
    if column.read_as == "decimal":
        # str() gives the shortest text for the float, which is the exact cents Quickbase holds.
        return Decimal(str(value))
    if value != int(value):
        # Rounding could silently change an amount. The value isn't shown, as it may be sensitive.
        raise InvalidResponseError(
            f"Field {column.label!r} is set to no decimal places, so it was generated as an int, "
            "but a record holds a fraction. Quickbase only uses that setting for display. Fix the "
            "record, or change the setting and run `pyquickbase codegen` again."
        )
    return int(value)


class TypedRecord:
    """The base of generated classes. One instance is one record, with a type for each field.

    `repr` shows only the record's shape, because values may be sensitive and reprs end up in logs.
    """

    __slots__ = ()
    # Generated files use these, `_row`, and positional `Column(...)`, and must keep working through
    # 1.x, so any new `Column` field needs a default. tests/_async/test_generated_contract.py checks
    # this.
    # `_row` can't collide with a field, because generated attribute names never start with `_`.
    __table_id__: ClassVar[str]
    __columns__: ClassVar[tuple[Column, ...]]

    @classmethod
    def from_record(cls, record: Record, *, only: Collection[int] | None = None) -> Self:
        """Build an instance from a record.

        Args:
            record: A `Record` with every field of the class, such as from `Table.query()`, or
                with the fields in `only`.
            only: The field IDs to read, for a record queried with `select`. The other
                attributes are left unset, so reading one raises `AttributeError`.

        Returns:
            An instance of the class.

        Raises:
            InvalidResponseError: The record is missing a field it should hold.
        """
        try:
            if only is None:
                return cls(
                    **{
                        column.name: _converted(column, record[column.id])
                        for column in cls.__columns__
                    }
                )
            # A frozen dataclass can only be partly filled in by going around its __init__.
            instance = object.__new__(cls)
            for column in cls.__columns__:
                if column.id in only:
                    value = _converted(column, record[column.id])
                    object.__setattr__(instance, column.name, value)
            return instance
        except KeyError as exc:
            raise InvalidResponseError(
                f"A {cls.__name__} record is missing a field. A report may have left it out, or "
                "your access may not include it."
            ) from exc

    @classmethod
    def _row(cls, values: dict[str, Any]) -> Row[Self]:
        ids = {column.name: column.id for column in cls.__columns__}
        kept = {ids[name]: value for name, value in values.items() if value is not UNSET}
        return Row(kept, table_id=cls.__table_id__)

    if not TYPE_CHECKING:
        # Hidden from type checkers, which would otherwise accept any attribute name. Python calls
        # this only when a lookup fails, as it does for an attribute that `select` left out.
        def __getattr__(self, name: str) -> Any:
            columns = getattr(type(self), "__columns__", ())
            if any(column.name == name for column in columns):
                raise AttributeError(
                    f"{type(self).__name__}.{name} wasn't selected in the query that read this "
                    "record, so it isn't here. Add it to select.",
                    name=name,
                    obj=self,
                )
            raise AttributeError(
                f"{type(self).__name__!r} object has no attribute {name!r}", name=name, obj=self
            )

    def __repr__(self) -> str:
        record_id = getattr(self, "id", None)
        return f"{type(self).__name__}(id={record_id!r}, fields={len(fields(self))})"  # pyright: ignore[reportArgumentType]


def rows_for(model: type[TypedRecord], rows: Iterable[Row[Any]]) -> list[Row[Any]]:
    """Refuse a row made for another table, whose field IDs would mean different fields here."""
    given = list(rows)
    for index, row in enumerate(given):
        table_id = getattr(row, "table_id", None)
        if table_id is not None and table_id != model.__table_id__:
            raise InvalidValueError(
                f"Row {index} was made for table {table_id}, not {model.__name__}. Its field IDs "
                "would mean different fields here, so nothing was written."
            )
    return given


def column_ids(model: type[TypedRecord]) -> list[int]:
    return [column.id for column in model.__columns__]


def select_ids(model: type[TypedRecord], select: Select) -> list[int] | None:
    """Turn `select` into the field IDs to read, with Record ID#, or None for every column."""
    if select is None:
        return None
    refs = [select] if isinstance(select, TypedField) else select
    if isinstance(refs, str) or not isinstance(refs, Iterable):  # pyright: ignore[reportUnnecessaryIsInstance]
        raise QueryError(_SELECT_HELP.format(name=model.__name__))
    ids: list[int] = []
    known = set(column_ids(model))
    for ref in refs:
        if not isinstance(ref, TypedField) or ref.id not in known:  # pyright: ignore[reportUnnecessaryIsInstance]
            raise QueryError(_SELECT_HELP.format(name=model.__name__))
        ids.append(ref.id)
    if not ids:
        raise QueryError("select needs at least one field.")
    return list(dict.fromkeys([RECORD_ID_FIELD, *ids]))


_SELECT_HELP = (
    "select takes fields of {name}, alone or in a list, such as {name}.fields.title, and not "
    "labels or IDs."
)


def schema_problems(model: type[TypedRecord], current: Iterable[Field]) -> list[str]:
    """Compare a generated class with the table as it is now."""
    by_id = {field.id: field for field in current}
    problems: list[str] = []
    for column in model.__columns__:
        field = by_id.get(column.id)
        if field is None:
            # Quickbase leaves out fields a role can't see, and so does a read policy, so these look
            # the same as deleted ones.
            problems.append(
                f"{column.name} (field {column.id}) no longer exists, or this client can't see it"
            )
        elif field.type != column.type:
            problems.append(f"{column.name} was {column.type} and is now {field.type}")
        elif column.read_as and read_as(field) != column.read_as:
            problems.append(f"{column.name} is no longer read as {column.read_as}")
        elif column.writable and not is_writable(field):
            # Only this direction. A later SDK can confirm more writable types, which mustn't fail
            # a class generated before that, and a class that won't write a field is still safe.
            problems.append(f"{column.name} is now read-only")
    return problems


def raise_for_problems(model: type[TypedRecord], problems: list[str]) -> None:
    if problems:
        raise SchemaMismatchError(
            f"{model.__name__} doesn't match its table: {'; '.join(problems)}. "
            "Run `pyquickbase codegen` again."
        )
